  if(ticks-at<30)return;
  if(phase==1){mc.player.getInventory().setSelectedSlot(0);((SpellContainerSource.Owner)mc.player).spellContainerCache().clear();SpellContainerSource.update(mc.player);lines.add("Client held="+mc.player.getMainHandItem()+" modifiers="+((SpellContainerSource.Owner)mc.player).getSpellContainers().modifiers());check(BlinkCharges.selected(mc.player),"Selected passive synchronized to client");check(BlinkCharges.available(m)==2,"Client bank2/2");mc.setScreenAndShow(null);mc.player.setYRot(0);mc.player.setXRot(0);shot("Blitz2of2");action=1;actionAt=ticks+10;step();return;}
  if(phase==2){if(ticks-at<65)return;check(BlinkCharges.available(m)==1,"Native first cast consumes one synchronized charge");lines.add("Blitz position="+mc.player.position()+" scale="+mc.player.getScale());check(Math.abs(mc.player.getZ()-7.5)<.1,"Controlled native Blitz travels 7.5 blocks");check(!mc.player.hasEffect(PaladinRevamp.effect("spell_engine:stun")),"Successful client/server Blink cleanses stun");check(!mc.player.hasEffect(net.minecraft.world.effect.MobEffects.SPEED),"Blitz grants no stale Speed");check(!m.isCoolingDown(PaladinRevamp.spell(mc.player,"wizards:arcane_blink")),"Remaining charge usable during recharge");shot("Blitz1of2-recharging");action=1;actionAt=ticks+10;step();return;}
  if(phase==3){if(ticks-at<65)return;check(BlinkCharges.available(m)==0,"Native second cast consumes final charge");var a=((SpellCaster.Client)mc.player).getCastController().startSpellCast(mc.player.getMainHandItem(),PaladinRevamp.spell(mc.player,"wizards:arcane_blink"));check(!a.result().toString().equals("SUCCESS"),"Native third cast rejected while empty");shot("Blitz0of2");action=2;actionAt=ticks+10;step();return;}
